{"code": "// Segments the score into phrases (groups separated by silences longer than `gap`), then
// picks adjacent note pairs within each phrase whose interval matches the chosen condition.
// Pairs that cross from one phrase to the next are never considered.

const params = {
  gap:      { type: "slider", range: [50, 2000], value: 300, unit: "ms" },
  interval: { type: "slider", range: [0, 1200], value: 300, unit: "mc" },
  mode:     { type: "menu", options: ["exact", "less than", "greater than"], value: "exact" },
};

function select(source, p) {
  const picked = [];
  for (const voice of source.voices) {
    phrases(voice, p.gap).forEach((phrase) => {
      const notes = [];
      for (const chord of phrase) for (const n of chord.notes) notes.push(n);
      notes.sort((a, b) => a.onset - b.onset || a.pitch - b.pitch);
      for (let i = 0; i + 1 < notes.length; i++) {
        const d = Math.abs(notes[i + 1].pitch - notes[i].pitch);
        let ok;
        if (p.mode === "exact") ok = d === p.interval;
        else if (p.mode === "less than") ok = d < p.interval;
        else ok = d > p.interval;
        if (ok) { picked.push(notes[i]); picked.push(notes[i + 1]); }
      }
    });
  }
  return picked;
}
